import{_ as e,c as o,b as s,o as n}from"./app-DKvarYBr.js";const i={};function r(a,t){return n(),o("div",null,t[0]||(t[0]=[s('<h3 id="discount" tabindex="-1"><a class="header-anchor" href="#discount"><span>Discount</span></a></h3><p>The Webkul Multivendor app now makes it easier for admins to empower sellers with discount management.</p><p>As an admin, you can decide whether sellers are allowed to create discounts directly from their dashboards.</p><p>Based on your configuration, sellers will be able to:</p><p>1- Create discounts on individual products<br> 2- Create discounts on the overall order</p><h3 id="create-discounts-on-products" tabindex="-1"><a class="header-anchor" href="#create-discounts-on-products"><span>Create Discounts On Products</span></a></h3><p>The admin needs to follow the steps to create discounts on products.</p><p><strong>Configuration: Admin End</strong></p><p>To configure this feature, follow the path:</p><p>Admin Dashboard&gt;&gt;Configuration&gt;&gt;Discount Configuration</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/dis1-1200x930.webp" alt="Discount(Admin end)"></p><p>Click &quot;Allow Seller to Create Discounts on Products&quot; and save the settings.</p><p>As soon as the admin configures these settings, sellers will get the option to create discounts on products from their respective seller panels.</p><p><strong>Seller Creating Discount on Product</strong></p><p>The seller needs to follow these simple steps to add discounts to products:</p><p>Go to the Product section&gt;&gt;Select Discount &gt;&gt;Add Discount button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/dis2-1200x571.webp" alt="Discount"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/product-1-961x1024.webp" alt="product"></p><p>Select the discount type (Percentage or Fixed), enter the discount value, and choose the product to apply it to.</p><p>Set the start and end dates to define the validity period of the discount, then save changes.</p><p>The seller will see all the discounts added to their store in the Discount section.</p><h3 id="create-discounts-on-order" tabindex="-1"><a class="header-anchor" href="#create-discounts-on-order"><span>Create Discounts On Order</span></a></h3><p>The admin needs to follow the steps to create discounts on overall orders.</p><p><strong>Configuration: Admin End</strong></p><p>To allow sellers to create discounts on the overall order, the admin needs to navigate to:</p><p>Admin Dashboard&gt;&gt;Configuration&gt;&gt;Discount Configuration</p><p>Enable “Allow Seller to Create Discounts on Overall Order” and save the settings.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/allow-1200x930.webp" alt="Allow"></p><p>Once configured, sellers will have the option to create discounts on the overall order from their respective seller panels.</p><p><strong>Seller Creating Discount on Order</strong></p><p>The seller needs to follow these steps to create discounts on overall orders:</p><p>Go to the Product section of the seller panel.</p><p>Select Discount from the drop-down menu.</p><p>Click the Add Discount button.</p><p>Select the Discount Type (Percentage or Fixed) and enter the discount value. Select &#39;Order&#39; as the discount applies to.</p><p>Set the start and end date of your discount as the validity period. Save changes.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/dis5-1003x1024.webp" alt="Dis"></p><p>The seller will see all discount codes added to their store in the Discount section.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/dis-1200x717.webp" alt="All sis counts"></p><p><strong>Please note: The overall order discount works based on the seller’s smart collection, and the discount will also be applied seller-wise on the front end.</strong></p><p><strong>Discount Status</strong></p><p>Scheduled: If the start date is in the future.</p><p>Active: If it has started but not yet ended.</p><p>Expired: If both the start and end dates have passed.</p><p><strong>Front end</strong></p><p>In order to display the discount on the front, you need to add the codes to the suggested liquid files (as shown in the screenshot).</p><p>So, go to the Multivendor Admin Panel and navigate to:</p><p>Configuration &gt;&gt;Instruction for Marketplace &gt;&gt; Scroll down to get the codes for “Discount” &gt;&gt; Copy the code from there &amp; add it to the instructed liquid files.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/last-1200x571.webp" alt="codes"></p><p>In this way, the discount will be visible on the front.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/11/front-1200x535.webp" alt="Front"></p>',51)]))}const c=e(i,[["render",r]]),d=JSON.parse('{"path":"/classic/configuration/Discount%20Configuration.html","title":"Discount Configuration","lang":"en-US","frontmatter":{"title":"Discount Configuration","description":"Discount Configuration","date":"2025-09-10T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Discount","slug":"discount","link":"#discount","children":[]},{"level":3,"title":"Create Discounts On Products","slug":"create-discounts-on-products","link":"#create-discounts-on-products","children":[]},{"level":3,"title":"Create Discounts On Order","slug":"create-discounts-on-order","link":"#create-discounts-on-order","children":[]}],"git":{"updatedTime":1764586065000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"6da5a1c75e37f77fbe87cc39a942e54bbc8e175a","time":1764586065000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflict"}]},"filePathRelative":"classic/configuration/Discount Configuration.md"}');export{c as comp,d as data};
